// Robinson's Zoetrope in a post: the Play dialog.
//
// Progressive enhancement over a plain link, on citation-figure.js's
// pattern. Without this script -- or in an engine without
// <dialog>.showModal() -- the Play link opens the toy's own page. With it,
// the same page opens in an <iframe> inside a dialog. The dialog is built on
// the first click and kept, so the toy's page loads only when a reader asks
// for it (DELIVERY 29e, 18:29 and 18:56). The page is same-origin, so the
// frame is sized to the page it holds, and the dialog scrolls rather than
// the frame. Dialog handling follows initPerfPlate() in js/main.js.
//
// Written into the vault's js/ by mockups/memory-strip/build_zoetrope.py
// --place in the support repository, from zoetrope-robinson-post.js beside
// it, the only place to edit this script.

function initZoetropeRobinson() {
  const links = document.querySelectorAll('.zoetrope-robinson-open');
  if (!links.length || typeof HTMLDialogElement !== 'function' ||
      typeof HTMLDialogElement.prototype.showModal !== 'function') return;

  let dialog = null;
  const open = (e) => {
    e.preventDefault();
    // ??= assigns only when dialog is still null: the first click builds it.
    dialog ??= buildDialog(e.currentTarget.href);
    dialog.showModal();
  };
  for (const link of links) link.addEventListener('click', open);
}

function buildDialog(url) {
  const dialog = document.createElement('dialog');
  dialog.className = 'zoetrope-robinson-dialog';
  dialog.setAttribute('closedby', 'any');
  dialog.setAttribute('aria-labelledby', 'zr-dialog-title');
  dialog.innerHTML = `
    <div class="zr-dialog-head">
      <h2 id="zr-dialog-title">Robinson&rsquo;s Zoetrope</h2>
      <button type="button" class="zr-dialog-close" aria-label="Close">&times;</button>
    </div>
    <iframe class="zr-frame" title="Robinson&rsquo;s Zoetrope, interactive"></iframe>`;
  const frame = dialog.querySelector('.zr-frame');

  // The frame takes its address here, on the first open, never at page load.
  frame.src = url;

  // Once the toy's page has loaded, two things reach into it, which the
  // same origin allows. Its height: the toy reflows with the dialog's width,
  // so a ResizeObserver on its body keeps the frame fitted. And Escape: a key
  // pressed inside the frame goes to the frame's own document, not to the
  // dialog, so the frame's Escape is passed on to close the dialog.
  frame.addEventListener('load', () => {
    const doc = frame.contentDocument;
    if (!doc || !doc.body) return;
    const fit = () => { frame.style.height = doc.documentElement.scrollHeight + 'px'; };
    new ResizeObserver(fit).observe(doc.body);
    fit();
    doc.addEventListener('keydown', (e) => { if (e.key === 'Escape') dialog.close(); });
  });

  document.body.append(dialog);
  dialog.querySelector('.zr-dialog-close').addEventListener('click', () => dialog.close());

  // Light dismiss where closedby="any" is unimplemented: initPerfPlate's
  // test, unchanged.
  if (!('closedBy' in HTMLDialogElement.prototype)) {
    dialog.addEventListener('click', (e) => {
      if (e.target !== dialog) return;
      const box = dialog.getBoundingClientRect();
      const inside = e.clientX >= box.left && e.clientX <= box.right
                  && e.clientY >= box.top && e.clientY <= box.bottom;
      if (!inside) dialog.close();
    });
  }
  return dialog;
}

// A deferred script runs after the document is parsed and before
// DOMContentLoaded fires, so the listener is registered in time.
document.addEventListener('DOMContentLoaded', initZoetropeRobinson);
